const N = {{rows}};
const rows = Array.from({ length: N }, (_, i) => ({ id: i, v: (i * 2654435761) % N }));
const index = new Map(rows.map((r) => [r.v, r]));
const key = rows[(N / 2) | 0].v;
let t0 = performance.now();
rows.find((r) => r.v === key);
const scan = performance.now() - t0;
t0 = performance.now();
index.get(key);
const seek = performance.now() - t0;
ctx.clearRect(0, 0, W(), H());
ctx.fillStyle = '#eee'; ctx.font = '15px system-ui';
ctx.fillText(N.toLocaleString() + '행에서 한 건 찾기', 16, 30);
const bar = (y, ms, label, col) => {
  const w = Math.max(3, Math.min(W() - 170, ms * 60));
  ctx.fillStyle = col; ctx.fillRect(16, y, w, 22);
  ctx.fillStyle = '#eee'; ctx.font = '13px ui-monospace, monospace';
  ctx.fillText(label + ' ' + ms.toFixed(3) + 'ms', 24 + w, y + 17);
};
bar(56, scan, '전체 훑기', '#f87171');
bar(92, seek, '인덱스', '#4ade80');
ctx.fillStyle = '#9ca3af'; ctx.font = '12px system-ui';
ctx.fillText('행이 늘수록 훑기만 느려진다 — 인덱스는 거의 그대로', 16, 140);

